import re,json
from pathlib import Path
p=Path('docs/design')
s=Path('src/ui/tokens.css').read_text(encoding='utf-8')
old=dict(re.findall(r'(--[\w-]+)\s*:\s*([^;]+);',s))
new={**old, '--bg-app':'#141719','--bg-sidebar':'#101315','--bg-panel':'#1D2225','--bg-raised':'#272D31','--bg-hover':'#323A3F','--bg-selected':'#3A302A','--border-subtle':'#363E43','--border-control':'#849095','--text-primary':'#F2EEE7','--text-secondary':'#C8C7C2','--text-muted':'#A2A8AA','--accent':'#F4AD82','--accent-hover':'#FFC69F','--accent-pressed':'#DE966F','--on-accent':'#241810','--amber':'#E6C66D','--amber-bg':'#35301F','--orange':'#F3B18A','--success':'#91CFAB','--success-bg':'#22352C','--danger':'#F09B9E','--danger-bg':'#3B272B','--branch-conditioning':'#91CFAB','--branch-mobility':'#91BDE6','--branch-survival':'#C6AFF1','--radius-panel':'8px','--radius-dialog':'12px','--shadow-dialog':'0 24px 64px #00000080','--backdrop':'#080B0DCC'}
new.update({'--warning':'var(--amber)','--warning-bg':'var(--amber-bg)','--info':'#91BDE6','--info-bg':'#24323E','--accent-bg':'var(--bg-selected)','--accent-border':'#B78060','--warning-border':'#A89255','--success-border':'#6E9D81','--danger-border':'#AF7378','--info-border':'#6D91B1','--orange-bg':'#392E26','--orange-border':'#B48266','--danger-hover-bg':'#503137','--danger-pressed-bg':'#633A41','--surface-inset':'#181C1F','--chart-1':'#F4AD82','--chart-2':'#91BDE6','--chart-3':'#91CFAB','--chart-4':'#C6AFF1','--chart-5':'#E6C66D','--chart-6':'#F09B9E','--chart-7':'#79CECC','--chart-grid':'#465158','--font-size-xs':'12px','--font-size-sm':'13px','--font-size-md':'14px','--font-size-lg':'16px','--font-size-h3':'16px','--font-size-h2':'18px','--font-size-h1':'28px','--font-size-kpi':'32px','--font-size-stat':'24px','--font-size-clock':'44px','--line-xs':'18px','--line-sm':'20px','--line-md':'22px','--line-lg':'24px','--line-h1':'36px','--line-kpi':'40px','--line-clock':'52px','--weight-regular':'400','--weight-medium':'500','--weight-semibold':'600','--weight-bold':'700','--tracking-label':'0.06em','--tracking-head':'0.01em','--space-0':'0','--space-half':'2px','--radius-pill':'999px','--shadow-panel':'none','--shadow-popover':'0 12px 32px #00000059','--line-thin':'1px','--line-strong':'2px','--line-indicator':'3px','--focus-width':'2px','--focus-offset':'3px','--focus-color':'var(--accent)','--duration-fast':'120ms','--duration-dialog':'160ms','--duration-slow':'240ms','--ease-out':'cubic-bezier(0.2, 0, 0, 1)','--control-sm':'32px','--control-md':'36px','--control-lg':'44px','--table-row-h':'44px','--table-head-h':'36px','--nav-item-h':'36px','--sidebar-compact-w':'64px','--page-max-w':'1680px'})
css=':root {\n'+''.join(f'  {k}: {v};\n' for k,v in new.items())+'}\n'
(p/'tokens-v2.css').write_text(css,encoding='utf-8')
rows=['| Existující token | Stará hodnota | Náhrada v novém bloku |','|---|---|---|']+[f'| `{k}` | `{v}` | `{new[k]}` |' for k,v in old.items()]
(p/'token-mapping.md').write_text('\n'.join(rows)+'\n',encoding='utf-8')
def lum(h):
 a=[int(h[i:i+2],16)/255 for i in (1,3,5)]; return sum((v/12.92 if v<=.04045 else ((v+.055)/1.055)**2.4)*w for v,w in zip(a,[.2126,.7152,.0722]))
def ratio(a,b):
 x,y=sorted([lum(a),lum(b)]);return (y+.05)/(x+.05)
pairs=[('--text-primary','--bg-app'),('--text-primary','--bg-panel'),('--text-secondary','--bg-panel'),('--text-muted','--bg-panel'),('--text-muted','--bg-raised'),('--text-muted','--bg-hover'),('--text-primary','--bg-selected'),('--on-accent','--accent'),('--on-accent','--accent-pressed'),('--success','--success-bg'),('--danger','--danger-bg'),('--amber','--amber-bg'),('--info','--info-bg'),('--border-control','--bg-raised'),('--accent','--bg-panel')]
cs=['| Popředí | Pozadí | Poměr | Použití |','|---|---|---:|---|']+[f'| `{a}` | `{b}` | {ratio(new[a],new[b]):.2f}:1 | '+('Hranice ovládání, cíl ≥ 3:1' if a=='--border-control' else 'Text, cíl ≥ 4,5:1')+' |' for a,b in pairs]
(p/'contrast.md').write_text('\n'.join(cs)+'\n',encoding='utf-8')
print(json.dumps({'oldTokens':len(old),'newTokens':len(new),'missing':list(set(old)-set(new))}))
